use threadpool::ThreadPool;

fn listen_bounded() {
    let pool = ThreadPool::new(64); // Fixed thread pool
    let listener = std::net::TcpListener::bind("0.0.0.0:8080").unwrap();
    for stream in listener.incoming() {
        if let Ok(s) = stream {
            pool.execute(move || {
                handle_client(s);
            });
